import { Agent, Memory } from '@voltagent/core';
import { LibSQLMemoryAdapter as LibSQLStorage } from '@voltagent/libsql';
import { openai } from '@ai-sdk/openai';

const storage = new LibSQLStorage({
  url: 'file:memory.db',
});

const agent = new Agent({
  name: 'MemoryAgent',
  instructions: 'You remember things.',
  model: openai('gpt-4o'),
  memory: new Memory({ storage }),
});

async function main() {
  console.log('Running MemoryAgent...');

  // Create a conversation and add a message to ensure the DB is initialized
  try {
    await storage.createConversation({
      id: 'conv-1',
      userId: 'user-1',
      resourceId: 'resource-1',
      title: 'Hello',
      metadata: {},
    });

    await storage.addMessage(
      { role: 'user', content: 'Hello' },
      'user-1',
      'conv-1'
    );
    console.log('MemoryAgent initialized successfully.');
  } catch (error) {
    // If conversation already exists, it's fine
    if ((error as any).code === 'CONVERSATION_ALREADY_EXISTS') {
      console.log('MemoryAgent already initialized.');
    } else {
      console.error('Error during initialization:', error);
    }
  }
}

if (require.main === module) {
  main().catch(console.error);
}

