import { Agent, Memory } from '@voltagent/core';
import { LibSQLMemoryAdapter as LibSQLStorage } from '@voltagent/libsql';
import { openai } from '@ai-sdk/openai';

const storage = new LibSQLStorage({
  url: 'file:memory.db',
});

const agent = new Agent({
  name: 'MemoryAgent',
  instructions: 'You remember things.',
  model: openai('gpt-4o'),
  memory: new Memory({ storage }),
});

async function main() {
  console.log('Running MemoryAgent...');

  // Just initialize the storage to create the database file
  try {
    // Calling getConversation will trigger initialization/table creation
    await storage.getConversation('any-id');
    console.log('MemoryAgent initialized successfully.');
  } catch (error) {
    console.error('Error during initialization:', error);
  }
}

if (require.main === module) {
  main().catch(console.error);
}

